// Draw a stack of vinyl records
const recordWidth = 250;
const recordHeight = 150;
const margin = 30;
const stackHeight = 300;

// Create a palette for vintage records
const palette = [
  '#2c184c', // dark red
  '#5d4037', // warm brown
  '#8d6e63', // earthy brown
  '#4e342e', // dark brown
  '#3e2723', // dark brown
  '#ffffff' // white label
];

// Draw records
let y = H - stackHeight;
for (let i = 0; i < 5; i++) {
  const radius = recordWidth / 2;
  const cx = W / 2 - recordWidth / 2 + margin;

  // Record body
  ctx.fillStyle = palette[i % palette.length];
  ctx.beginPath();
  ctx.arc(cx, y, radius, 0, Math.PI * 2);
  ctx.fill();

  // Record label
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(cx, y, radius * 0.6, 0, Math.PI * 2);
  ctx.fill();

  // Label details
  ctx.fillStyle = '#000000';
  ctx.font = '10px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(`LP ${i+1}`, cx, y + radius * 0.65);

  // Grooves
  ctx.strokeStyle = '#2c184c';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, y, radius, 0, Math.PI * 2);
  ctx.stroke();

  // Spikes
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 3;
  for (let j = 0; j < 10; j++) {
    const angle = (j / 10) * Math.PI * 2;
    const x = cx + Math.cos(angle) * radius * 0.7;
    const y2 = cy + Math.sin(angle) * radius * 0.7;
    ctx.beginPath();
    ctx.moveTo(cx, y);
    ctx.lineTo(x, y2);
    ctx.stroke();
  }

  // Shadow under each record
  if (i > 0) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
    ctx.beginPath();
    ctx.ellipse(cx, y + radius, radius * 0.6, 5, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  y -= recordHeight + 10;
}

