// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Define circle colors
const colors = [
  '#ffd166', // pastel orange
  '#4ecdc4', // pastel cyan
  '#45b7d1', // pastel blue
  '#96ceb4', // pastel green
  '#feca57', // pastel yellow
  '#ff6b9d'  // pastel pink
];

// Draw circles
for (let r = 0; r <= maxRadius; r += 30) {
  const alpha = (r / maxRadius) * 0.8;
  ctx.globalAlpha = alpha;
  ctx.beginPath();
  ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
  ctx.strokeStyle = colors[r / 30 % 6];
  ctx.lineWidth = 3;
  ctx.stroke();
}

// Draw inner circles
for (let r = 0; r <= maxRadius; r += 20) {
  if (r > 0) {
    const alpha = (r / maxRadius) * 0.6;
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.stroke();
  }
}

// Draw radial lines
ctx.strokeStyle = '#fff';
ctx.lineWidth = 1;
for (let i = 0; i < 12; i++) {
  const angle = (i / 12) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * maxRadius;
  const startY = centerY + Math.sin(angle) * maxRadius;
  const endX = centerX + Math.cos(angle) * (maxRadius + 50);
  const endY = centerY + Math.sin(angle) * (maxRadius + 50);
  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

// Draw geometric shapes
ctx.strokeStyle = '#000';
ctx.lineWidth = 2;
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const x = centerX + Math.cos(angle) * (maxRadius - 40);
  const y = centerY + Math.sin(angle) * (maxRadius - 40);

  // Draw triangles
  ctx.beginPath();
  ctx.moveTo(centerX, centerY);
  ctx.lineTo(x, y);
  ctx.lineTo(x + 30 * Math.cos(angle + Math.PI/2), y + 30 * Math.sin(angle + Math.PI/2));
  ctx.closePath();
  ctx.stroke();

  // Draw hexagons
  ctx.beginPath();
  ctx.moveTo(x, y);
  for (let j = 0; j < 6; j++) {
    const angleOffset = (j / 6) * Math.PI * 2;
    const xx = x + Math.cos(angle + angleOffset) * 30;
    const yy = y + Math.sin(angle + angleOffset) * 30;
    ctx.lineTo(xx, yy);
  }
  ctx.closePath();
  ctx.stroke();
}

