// Draw spiral in cool tones
function drawSpiral(x, y, len, dir, color) {
    if (len > 0) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(dir) * len, y + Math.sin(dir) * len);
        ctx.lineTo(x + Math.cos(dir) * len + Math.cos(dir + Math.PI/4) * len/2, 
                    y + Math.sin(dir) * len + Math.sin(dir + Math.PI/4) * len/2);
        ctx.lineTo(x + Math.cos(dir) * len, y + Math.sin(dir) * len);
        ctx.fill();

        // Recursive call for next segment
        drawSpiral(
            x + Math.cos(dir) * len + Math.cos(dir + Math.PI/4) * len/2, 
            y + Math.sin(dir) * len + Math.sin(dir + Math.PI/4) * len/2, 
            len * 0.85, 
            dir + Math.PI/8, 
            color
        );
    }
}

