// Jellyfish body - glowing sphere
const cx = 200;
const cy = 200;
const radius = 40;

// Main jellyfish body - soft gradient glow
ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(255, 255, 0, 0.3)';
ctx.fill();

// Add gradient highlights
const gradient = ctx.createRadialGradient(
    cx, cy, radius/2,
    cx, cy, radius
);
gradient.addColorStop(0, 'rgba(255, 255, 0, 0.5)');
gradient.addColorStop(1, 'rgba(255, 255, 0, 0.1)');

ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fillStyle = gradient;
ctx.fill();

// Add pulsating inner glow
ctx.beginPath();
ctx.arc(cx, cy, radius * 0.6, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(255, 255, 0, 0.7)';
ctx.fill();

// Add pulsating outer glow
ctx.beginPath();
ctx.arc(cx, cy, radius * 1.2, 0, Math.PI * 2);
ctx.fillStyle = 'rgba(255, 255, 0, 0.3)';
ctx.fill();

// Add tentacles
const tentacleCount = 8;
const length = 60;
const width = 4;

for(let i = 0; i < tentacleCount; i++) {
    const angle = (i / tentacleCount) * Math.PI * 2;
    const x1 = cx + Math.cos(angle) * radius * 1.5;
    const y1 = cy + Math.sin(angle) * radius * 1.5;

    const x2 = cx + Math.cos(angle) * (radius * 1.5 + length);
    const y2 = cy + Math.sin(angle) * (radius * 1.5 + length);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);

    // Tentacle details - soft gradient
    const tGradient = ctx.createLinearGradient(x1, y1, x2, y2);
    tGradient.addColorStop(0, 'rgba(255, 255, 0, 1)');
    tGradient.addColorStop(1, 'rgba(255, 255, 0, 0.3)');

    ctx.strokeStyle = tGradient;
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
}

